function cp_check($ok,$label){global $checks;if(!$ok)throw new Exception($label);$checks[]=$label;}
$filter=function($value,$atts)use(&$mail,&$transport){$attachments=$atts['attachments'];$mail[]=array('subject'=>$atts['subject'],'pdf'=>!empty($attachments)&&is_file(reset($attachments)));if($transport==='unknown')throw new RuntimeException('Synthetic uncertain transport');return $transport==='success';};add_filter('pre_wp_mail',$filter,PHP_INT_MAX,2);
