$logs=get_posts(array('post_type'=>GE_WTP_Notifications::LOG_POST_TYPE,'post_status'=>'private','numberposts'=>-1,'meta_key'=>'_ge_email_object_id','meta_value'=>$id));cp_check(count($logs)===1&&get_post_meta($logs[0]->ID,'_ge_email_result',true)==='failed','Actual notification log records failed transport');
$events=get_post_meta($id,'_ge_commercial_events',true);cp_check(count(array_filter($events,function($e){return $e['event']==='published';}))===1&&count(array_filter($events,function($e){return in_array($e['event'],array('accepted','accepted_staff','converted'),true);}))===0,'Publishing records operator approval without customer acceptance or production approval');
GE_WTP_Commercial_Quotes::send($id,1,1,'publish-fixture');cp_check(count($mail)===1,'Repeated publication does not retry failed mail');
GE_WTP_Commercial_Quotes::send($id,1,1,'another-publish-click');cp_check(count($mail)===1,'Repeated publication with a new request never resends');
wp_set_current_user($ctx['customer']);$_GET=array();cp_check(in_array($id,array_column(GE_WTP_Portal_Quotes::customer_quotes(),'id'),true),'Customer can see published proposal even if notice failed');wp_set_current_user(1);
$_GET=array('quote_id'=>$id);ob_start();GE_WTP_Commercial_Quote_UI::render_staff();$html=ob_get_clean();cp_check(strpos($html,'Publicado; aviso no enviado')!==false&&strpos($html,'Reintentar aviso')!==false,'Staff detail explains partial success and offers explicit retry');
$transport='success';$result=GE_WTP_Commercial_Quotes::resend($id,1,1,'retry-fixture');cp_check(!is_wp_error($result)&&count($mail)===2,'Explicit retry succeeds without fiscal publication gate');
GE_WTP_Commercial_Quotes::resend($id,1,1,'retry-fixture');cp_check(count($mail)===2,'Repeated retry request is idempotent');
cp_check(get_post_meta($id,'_ge_commercial_notice',true)['status']==='sent'&&get_post_meta($id,GE_WTP_Commercial_Quotes::CURRENT_META,true)==1,'Retry only updates delivery result and preserves version');
cp_check(is_wp_error(GE_WTP_Billing_Issuers::validate_current($s['issuer_snapshot'])),'Fiscal issuer readiness still enforced for fiscal operations');
$stale=GE_WTP_Commercial_Quotes::resend($id,1,2,'stale-fixture');cp_check(is_wp_error($stale)&&$stale->get_error_code()==='ge_quote_version'&&count($mail)===2,'Stale version does not send');
add_option('ge_quote_publish_notice_'.$id,time(),'',false);$busy=GE_WTP_Commercial_Quotes::resend($id,1,1,'concurrent-fixture');delete_option('ge_quote_publish_notice_'.$id);cp_check(is_wp_error($busy)&&$busy->get_error_code()==='ge_quote_busy'&&count($mail)===2,'Concurrent action cannot send duplicate notice');
add_option('ge_quote_publish_notice_'.$id,time(),'',false);$edit=GE_WTP_Commercial_Quotes::revise($id,array(),array(),1);$billing=GE_WTP_Quote_Billing_Control::select($id,array(),1);delete_option('ge_quote_publish_notice_'.$id);cp_check(is_wp_error($edit)&&$edit->get_error_code()==='ge_quote_busy'&&is_wp_error($billing)&&$billing->get_error_code()==='ge_quote_busy','Revision and billing edits share publication lock to preserve exact PDF version');
