$incomplete=$s;$incomplete['draft_incomplete']=true;$unfinished=cp_quote($incomplete,$ctx['customer']);$denied=GE_WTP_Commercial_Quotes::send($unfinished,1,1);cp_check(is_wp_error($denied)&&$denied->get_error_code()==='ge_quote_incomplete'&&get_post_meta($unfinished,GE_WTP_Commercial_Quotes::STATUS_META,true)==='draft','Missing commercial data remains an actionable draft');
