remove_filter('pre_wp_mail',$filter,PHP_INT_MAX);echo 'PASS '.count($checks)." commercial publication checks\n";file_put_contents(dirname(dirname($load)).'/commercial-publication-results.json',wp_json_encode(array('checks'=>count($checks),'passed'=>$checks),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
